import random, math
from fractions import Fraction

def euler_phi(n):
    result = n
    p = 2
    temp = n
    while p * p <= temp:
        if temp % p == 0:
            while temp % p == 0:
                temp //= p
            result -= result // p
        p += 1 if p == 2 else 2
    if temp > 1:
        result -= result // temp
    return result

def R_direct(N):
    M = N + 1
    total = 0
    for a in range(1, N+1):
        for b in range(1, N+1):
            total += (a * b) % M
    return total

def R_formula(N):
    M = N + 1
    total_phi_over_d = Fraction(0, 1)
    for d in range(1, M+1):
        if M % d == 0:
            total_phi_over_d += Fraction(euler_phi(d), d)
    M_f = Fraction(M, 1)
    R = (M_f**2 / 2) * (M_f - total_phi_over_d)
    assert R.denominator == 1
    return R.numerator

def test_random_R(trials=200):
    for _ in range(trials):
        N = random.randint(1, 30)
        direct = R_direct(N)
        formula = R_formula(N)
        if direct != formula:
            print(f"Discrepancy: N={N}, direct={direct}, formula={formula}")
            return False
    print(f"All {trials} random tests passed.")
    return True

test_random_R()
